def get_discount_rate(user_type, is_member, years_active):
    discount_lookup = {
        'student': [0.25, 0.3, 0.25],
        'senior': [0.2, 0.25, 0.2],
        'regular': [0.1, 0.15, 0.1]
    }
    rates = discount_lookup.get(user_type, [0])
    for i, modifier in enumerate(rates, start=1):
        if is_member and years_active > (5 if i > 1 else 0):
            return rates[i-1]
    return rates[0]

def calculate_discount(price, user_type, is_member, years_active):
    discount_rate = get_discount_rate(user_type, is_member, years_active)
    return price * (1 - discount_rate)
